import{_t as e,it as t,n,rt as r}from"./chunks/framework.D2cFUyj2.js";var i=JSON.parse(`{"title":"Packaging & Distribution","description":"","frontmatter":{},"headers":[{"level":2,"title":"1. Plugin Assembly Directory Structure","slug":"_1-plugin-assembly-directory-structure","link":"#_1-plugin-assembly-directory-structure","children":[]},{"level":2,"title":"2. Automated PostBuild Copy Configuration","slug":"_2-automated-postbuild-copy-configuration","link":"#_2-automated-postbuild-copy-configuration","children":[]},{"level":2,"title":"3. Embedding Localization Resources","slug":"_3-embedding-localization-resources","link":"#_3-embedding-localization-resources","children":[]},{"level":2,"title":"4. Versioning & Metadata","slug":"_4-versioning-metadata","link":"#_4-versioning-metadata","children":[]},{"level":2,"title":"5. Release Build & Architecture Artifacts","slug":"_5-release-build-architecture-artifacts","link":"#_5-release-build-architecture-artifacts","children":[]}],"relativePath":"dev-guide/packaging.md","filePath":"dev-guide/packaging.md","lastUpdated":1791112464000}`),a={name:`dev-guide/packaging.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="packaging-distribution" tabindex="-1">Packaging &amp; Distribution <a class="header-anchor" href="#packaging-distribution" aria-label="Permalink to “Packaging &amp; Distribution”">​</a></h1><p>This chapter details directory conventions for plugin assemblies, bundling third-party dependencies, embedding i18n JSON resources, and automated build deployment.</p><h2 id="_1-plugin-assembly-directory-structure" tabindex="-1">1. Plugin Assembly Directory Structure <a class="header-anchor" href="#_1-plugin-assembly-directory-structure" aria-label="Permalink to “1. Plugin Assembly Directory Structure”">​</a></h2><p>Lertaro recursively scans the <code>Plugins\\</code> folder located in the application root directory. To maintain clean isolation and avoid dependency conflicts across different plugins, place each plugin into its own dedicated subfolder:</p><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Lertaro/</span></span>
<span class="line"><span>├── Lertaro.App.exe</span></span>
<span class="line"><span>├── Lertaro.PluginSdk.dll</span></span>
<span class="line"><span>└── Plugins/</span></span>
<span class="line"><span>    └── MyCustomPlugin/</span></span>
<span class="line"><span>        ├── Lertaro.Plugins.MyCustomPlugin.dll   (Main Plugin Assembly)</span></span>
<span class="line"><span>        ├── ThirdParty.Managed.dll              (Managed Third-Party Dependency)</span></span>
<span class="line"><span>        └── NativeLibrary.dll                   (Native C/C++ Dependency — placed FLAT)</span></span></code></pre></div><ul><li><strong>Automatic Dependency Probing</strong>: When Lertaro loads the primary DLL via <code>Assembly.LoadFrom</code>, the .NET runtime automatically probes the plugin&#39;s folder for adjacent dependencies without cross-contaminating other plugins.</li><li><strong>Native dependencies sit next to the DLL, not under <code>runtimes\\&lt;rid&gt;\\native</code></strong>: shipped plugin projects set <code>&lt;GenerateDependencyFile&gt;false&lt;/GenerateDependencyFile&gt;</code>, so no <code>.deps.json</code> is produced and the runtime has no deps graph to resolve an RID subfolder from. A native library therefore has to be discoverable in the application base directory — copy it flat. This is also why the two architectures are published as separate artifacts rather than one combined installer: only one architecture&#39;s native copy can occupy that flat load directory.</li><li><strong>Native File Toleration</strong>: When non-.NET native binaries (e.g. <code>e_sqlite3.dll</code>) are encountered by the assembly scan, the loader logs them at <code>Debug</code> level and moves on instead of raising a false-positive <code>Error</code>.</li></ul><h2 id="_2-automated-postbuild-copy-configuration" tabindex="-1">2. Automated PostBuild Copy Configuration <a class="header-anchor" href="#_2-automated-postbuild-copy-configuration" aria-label="Permalink to “2. Automated PostBuild Copy Configuration”">​</a></h2><p>Add a <code>PostBuild</code> MSBuild target to your plugin&#39;s <code>.csproj</code> to deploy the output into the Lertaro debug directories on every successful build. This is what the in-repo plugin projects actually do — note the <strong>flat</strong> destination and the <strong>second copy for the Service</strong>, which is what makes an alias or translation provider available to the indexer as well as to the UI:</p><div class="language-xml"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">xml</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">Target</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> Name</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;PostBuild&quot;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> AfterTargets</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;PostBuildEvent&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  &lt;</span><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">Copy</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> SourceFiles</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;$(TargetDir)$(TargetName).dll&quot;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">        DestinationFolder</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;..\\..\\App\\bin\\$(Configuration)\\net10.0-windows\\Plugins\\&quot;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">        SkipUnchangedFiles</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;true&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> /&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  &lt;</span><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">Copy</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> SourceFiles</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;$(TargetDir)$(TargetName).dll&quot;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">        DestinationFolder</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;..\\..\\Service\\bin\\$(Configuration)\\net10.0-windows\\Plugins\\&quot;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">        SkipUnchangedFiles</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;true&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> /&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;/</span><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">Target</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span></code></pre></div><p>Copy third-party managed or native dependencies to the same folder in a sibling <code>&lt;Copy&gt;</code> item if your plugin needs them at load time.</p><h2 id="_3-embedding-localization-resources" tabindex="-1">3. Embedding Localization Resources <a class="header-anchor" href="#_3-embedding-localization-resources" aria-label="Permalink to “3. Embedding Localization Resources”">​</a></h2><p>If your plugin implements the <a href="./sdk/ui-extensions.html"><code>ITranslationProvider</code></a> interface, embed your translation JSON files directly as <strong>Embedded Resources</strong> to prevent missing language files:</p><div class="language-xml"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">xml</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">ItemGroup</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  &lt;</span><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">EmbeddedResource</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> Include</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Resources\\Translations\\**\\*.json&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> /&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;/</span><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">ItemGroup</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span></code></pre></div><p>Organize files as <code>Resources/Translations/{culture}/{type}.json</code>, where <code>{type}</code> is the <code>typeName</code> you pass to <code>TranslationService.LoadEmbeddedTranslations(assembly, cultureKey, typeName)</code>. Every plugin in this repository uses the fixed file name <strong><code>Plugin.json</code></strong> (<code>Resources/Translations/zh-CN/Plugin.json</code>, <code>Resources/Translations/en-US/Plugin.json</code>, …) and passes <code>&quot;Plugin&quot;</code>; <code>App.json</code> is not a plugin convention — it exists only in CoreExtensions, which also supplies the host&#39;s own UI strings. The culture folders follow the app&#39;s seven locales; when the requested culture has no folder, the translation manager falls back to the plugin&#39;s first supported culture, then to <code>en-US</code>, and only then to the <code>[key]</code> placeholder.</p><h2 id="_4-versioning-metadata" tabindex="-1">4. Versioning &amp; Metadata <a class="header-anchor" href="#_4-versioning-metadata" aria-label="Permalink to “4. Versioning &amp; Metadata”">​</a></h2><p>Define assembly version numbers and descriptions inside your <code>.csproj</code>:</p><div class="language-xml"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">xml</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">PropertyGroup</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  &lt;</span><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">Version</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;1.2.0&lt;/</span><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">Version</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  &lt;</span><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">AssemblyVersion</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;1.2.0.0&lt;/</span><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">AssemblyVersion</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  &lt;</span><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">FileVersion</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;1.2.0.0&lt;/</span><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">FileVersion</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  &lt;</span><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">Description</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;High-performance search source and context action extension plugin.&lt;/</span><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">Description</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;/</span><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">PropertyGroup</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span></code></pre></div><p>This version and description string will be presented automatically inside the <strong>Settings → Plugins</strong> card.</p><h2 id="_5-release-build-architecture-artifacts" tabindex="-1">5. Release Build &amp; Architecture Artifacts <a class="header-anchor" href="#_5-release-build-architecture-artifacts" aria-label="Permalink to “5. Release Build &amp; Architecture Artifacts”">​</a></h2><p>Run <code>make.bat</code> from the repository root on Windows with the .NET SDK and the <a href="https://jrsoftware.org/isdl.php#v7" target="_blank" rel="noreferrer">64-bit edition of Inno Setup 7</a> installed (the script verifies the compiler really is 7.x). It calls <code>:build_arch</code> twice: once with <code>ARCH=x64</code> (published with no RID, as it always has been) and once with <code>ARCH=arm64</code> (a cross-publish with <code>-r win-arm64 --self-contained false</code>), producing four files in <code>dist/</code>:</p><ul><li><code>Lertaro-Setup.exe</code> and <code>Lertaro-Portable.zip</code> (x64).</li><li><code>Lertaro-Setup-arm64.exe</code> and <code>Lertaro-Portable-arm64.zip</code> (arm64).</li></ul><p>The two architectures ship as separate artifacts rather than one combined installer because the BrowserData plugin carries a native library, and its flat, deps.json-less load directory can hold only one architecture&#39;s native copy (see the header comment in the script). The arm64 installer differs from the x64 one in <code>Installer/installer.iss</code> in <code>ArchitecturesAllowed</code> (<code>arm64</code> vs <code>x64compatible</code>), <code>ArchitecturesInstallIn64BitMode</code>, <code>SetupArchitecture=x64</code> (set only for x64), the bundled .NET desktop runtime file and download URL, <code>PublishDir</code>, and the output file name; the payload inside each is native to its architecture. The release workflow hashes and uploads exactly these four names, and <code>UpdateAssetSelector</code> matches older installs by name — renaming an artifact would strand existing users. Keep artifact names aligned with <code>make.bat</code>, <code>Installer/installer.iss</code>, and the release workflow&#39;s asset list.</p>`,22)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};